dashboard.definition:
{
    "title": "BTC Mempool Explorer",
    "description": "mempool.space-style views over the btc_parser exports (index=btc_parser)",
    "inputs": {
        "input_time": {
            "type": "input.timerange",
            "title": "Time range",
            "options": {
                "token": "global_time",
                "defaultValue": "-30d@d,now"
            }
        },
        "input_span": {
            "type": "input.dropdown",
            "title": "Bucket",
            "options": {
                "token": "span",
                "defaultValue": "1d",
                "items": [
                    {
                        "label": "10 minutes",
                        "value": "10m"
                    },
                    {
                        "label": "1 hour",
                        "value": "1h"
                    },
                    {
                        "label": "4 hours",
                        "value": "4h"
                    },
                    {
                        "label": "1 day",
                        "value": "1d"
                    },
                    {
                        "label": "1 week",
                        "value": "1w"
                    },
                    {
                        "label": "1 month",
                        "value": "1mon"
                    }
                ]
            }
        },
        "input_idx": {
            "type": "input.text",
            "title": "Index",
            "options": {
                "token": "idx",
                "defaultValue": "btc_parser"
            }
        },
        "input_addr": {
            "type": "input.text",
            "title": "Address (Records)",
            "options": {
                "token": "addr"
            }
        }
    },
    "defaults": {
        "dataSources": {
            "ds.search": {
                "options": {
                    "queryParameters": {
                        "earliest": "$global_time.earliest$",
                        "latest": "$global_time.latest$"
                    }
                }
            }
        }
    },
    "visualizations": {
        "viz_kpi_price": {
            "type": "splunk.singlevalue",
            "options": {
                "majorValue": "> primary | seriesByName('USD') | lastPoint()",
                "sparklineDisplay": "below",
                "trendDisplay": "off",
                "unit": "$",
                "unitPosition": "before",
                "numberPrecision": 0,
                "majorColor": "#f7931a",
                "sparklineValues": "> primary | seriesByName('USD')",
                "sparklineStrokeColor": "#f7931a"
            },
            "title": "BTC / USD (now)",
            "dataSources": {
                "primary": "ds_price_24h"
            }
        },
        "viz_kpi_change": {
            "type": "splunk.singlevalue",
            "options": {
                "majorValue": "> primary | seriesByName('change_pct') | lastPoint()",
                "sparklineDisplay": "off",
                "trendDisplay": "off",
                "unit": "%",
                "unitPosition": "after",
                "numberPrecision": 2,
                "majorColor": "> majorValue | rangeValue(changeColors)"
            },
            "title": "24h change",
            "dataSources": {
                "primary": "ds_price_24h_change"
            },
            "context": {
                "changeColors": [
                    {
                        "to": 0,
                        "value": "#dc3545"
                    },
                    {
                        "from": 0,
                        "value": "#3bcc49"
                    }
                ]
            }
        },
        "viz_kpi_height": {
            "type": "splunk.singlevalue",
            "options": {
                "majorValue": "> primary | seriesByName('height') | lastPoint()",
                "sparklineDisplay": "off",
                "trendDisplay": "off",
                "numberPrecision": 0,
                "majorColor": "#1bd8f4",
                "shouldUseThousandSeparators": false
            },
            "title": "Block height",
            "dataSources": {
                "primary": "ds_tip"
            }
        },
        "viz_kpi_median_fee": {
            "type": "splunk.singlevalue",
            "options": {
                "majorValue": "> primary | seriesByName('median_fee') | lastPoint()",
                "sparklineDisplay": "off",
                "trendDisplay": "off",
                "unit": "sat/vB",
                "unitPosition": "after",
                "numberPrecision": 1,
                "majorColor": "#ffc107"
            },
            "title": "Tip block median fee",
            "dataSources": {
                "primary": "ds_tip"
            }
        },
        "viz_kpi_blocktime": {
            "type": "splunk.singlevalue",
            "options": {
                "majorValue": "> primary | seriesByName('avg_block_min') | lastPoint()",
                "sparklineDisplay": "off",
                "trendDisplay": "off",
                "unit": "min",
                "unitPosition": "after",
                "numberPrecision": 2,
                "majorColor": "#4a68b9"
            },
            "title": "Avg block time (range)",
            "dataSources": {
                "primary": "ds_range_stats"
            }
        },
        "viz_kpi_hashrate": {
            "type": "splunk.singlevalue",
            "options": {
                "majorValue": "> primary | seriesByName('hashrate_ehs') | lastPoint()",
                "sparklineDisplay": "off",
                "trendDisplay": "off",
                "unit": "EH/s",
                "unitPosition": "after",
                "numberPrecision": 1,
                "majorColor": "#9339f4"
            },
            "title": "Avg hashrate (range)",
            "dataSources": {
                "primary": "ds_range_stats"
            }
        },
        "viz_price_overview": {
            "type": "splunk.area",
            "options": {
                "legendDisplay": "bottom",
                "xAxisTitleVisibility": "hide",
                "nullValueDisplay": "connect",
                "seriesColors": [
                    "#f7931a",
                    "#4a68b9"
                ],
                "areaOpacity": 0.25,
                "yAxisTitleText": "Fiat"
            },
            "title": "BTC price",
            "dataSources": {
                "primary": "ds_price_range"
            }
        },
        "viz_fee_rates_overview": {
            "type": "splunk.line",
            "options": {
                "legendDisplay": "bottom",
                "xAxisTitleVisibility": "hide",
                "nullValueDisplay": "connect",
                "seriesColors": [
                    "#ffc107",
                    "#f7931a"
                ],
                "yAxisTitleText": "sat/vB"
            },
            "title": "Block fee rates",
            "dataSources": {
                "primary": "ds_fee_rates_blocks"
            },
            "description": "Median of per-block median fee rate vs. average fee rate (sat/vB)"
        },
        "viz_latest_blocks": {
            "type": "splunk.table",
            "options": {
                "count": 10,
                "columnFormat": {
                    "Median sat/vB": {
                        "rowBackgroundColors": "> table | seriesByName(\"Median sat/vB\") | rangeValue(feeColors)"
                    },
                    "Avg sat/vB": {
                        "rowBackgroundColors": "> table | seriesByName(\"Avg sat/vB\") | rangeValue(feeColors)"
                    },
                    "Full %": {
                        "rowBackgroundColors": "> table | seriesByName(\"Full %\") | rangeValue(fullColors)"
                    }
                }
            },
            "title": "Latest blocks",
            "dataSources": {
                "primary": "ds_latest_blocks"
            },
            "description": "Like mempool.space's block strip - fee colors use the mempool.space gradient",
            "context": {
                "feeColors": [
                    {
                        "value": "#557d00",
                        "to": 1
                    },
                    {
                        "value": "#5d7d01",
                        "from": 1,
                        "to": 2
                    },
                    {
                        "value": "#637d02",
                        "from": 2,
                        "to": 3
                    },
                    {
                        "value": "#6d7d04",
                        "from": 3,
                        "to": 4
                    },
                    {
                        "value": "#757d05",
                        "from": 4,
                        "to": 6
                    },
                    {
                        "value": "#867d08",
                        "from": 6,
                        "to": 8
                    },
                    {
                        "value": "#8c7d09",
                        "from": 8,
                        "to": 10
                    },
                    {
                        "value": "#957d0b",
                        "from": 10,
                        "to": 15
                    },
                    {
                        "value": "#a67d0e",
                        "from": 15,
                        "to": 20
                    },
                    {
                        "value": "#b27d10",
                        "from": 20,
                        "to": 30
                    },
                    {
                        "value": "#bf7815",
                        "from": 30,
                        "to": 50
                    },
                    {
                        "value": "#bd5c28",
                        "from": 50,
                        "to": 100
                    },
                    {
                        "value": "#bb3d3c",
                        "from": 100,
                        "to": 200
                    },
                    {
                        "value": "#b30e55",
                        "from": 200
                    }
                ],
                "fullColors": [
                    {
                        "to": 50,
                        "value": "#2b2d42"
                    },
                    {
                        "from": 50,
                        "to": 90,
                        "value": "#3a4a8a"
                    },
                    {
                        "from": 90,
                        "value": "#4a68b9"
                    }
                ]
            }
        },
        "viz_pool_pie_overview": {
            "type": "splunk.pie",
            "options": {},
            "title": "Mining pools (blocks in range)",
            "dataSources": {
                "primary": "ds_pool_top"
            }
        },
        "viz_throughput": {
            "type": "splunk.line",
            "options": {
                "legendDisplay": "bottom",
                "xAxisTitleVisibility": "hide",
                "nullValueDisplay": "connect",
                "seriesColors": [
                    "#1bd8f4",
                    "#f7931a"
                ],
                "overlayFields": [
                    "tx/s"
                ],
                "showOverlayY2Axis": true,
                "yAxisTitleText": "vB/s",
                "y2AxisTitleText": "tx/s"
            },
            "title": "Confirmed throughput",
            "dataSources": {
                "primary": "ds_throughput"
            },
            "description": "Mempool.space shows incoming vB/s; here: vB/s confirmed into blocks"
        },
        "viz_about": {
            "type": "splunk.markdown",
            "options": {
                "markdown": "#### About\nMempool.space-style views built on the **btc_parser** exports (`btc:blocks`, `btc:transactions`, `btc:inputs`, `btc:prices`, `btc:stale_block_headers`, `btc:sanctioned_tx_events`). There is no live mempool snapshot in the exports, so the \"mempool\" charts show what was **confirmed** in each time bucket. Charts over `btc:transactions`/`btc:inputs` scan every row - keep the time range short on a full export."
            }
        },
        "viz_epoch_progress": {
            "type": "splunk.singlevalue",
            "options": {
                "majorValue": "> primary | seriesByName('progress_pct') | lastPoint()",
                "sparklineDisplay": "off",
                "trendDisplay": "off",
                "unit": "%",
                "unitPosition": "after",
                "numberPrecision": 1,
                "majorColor": "#4a68b9"
            },
            "title": "Epoch progress",
            "dataSources": {
                "primary": "ds_epoch"
            }
        },
        "viz_epoch_remaining": {
            "type": "splunk.singlevalue",
            "options": {
                "majorValue": "> primary | seriesByName('remaining') | lastPoint()",
                "sparklineDisplay": "off",
                "trendDisplay": "off",
                "numberPrecision": 0,
                "majorColor": "#1bd8f4"
            },
            "title": "Blocks to retarget",
            "dataSources": {
                "primary": "ds_epoch"
            }
        },
        "viz_epoch_change": {
            "type": "splunk.singlevalue",
            "options": {
                "majorValue": "> primary | seriesByName('est_change_pct') | lastPoint()",
                "sparklineDisplay": "off",
                "trendDisplay": "off",
                "unit": "%",
                "unitPosition": "after",
                "numberPrecision": 2,
                "majorColor": "> majorValue | rangeValue(changeColors)"
            },
            "title": "Est. difficulty change",
            "dataSources": {
                "primary": "ds_epoch"
            },
            "context": {
                "changeColors": [
                    {
                        "to": 0,
                        "value": "#dc3545"
                    },
                    {
                        "from": 0,
                        "value": "#3bcc49"
                    }
                ]
            }
        },
        "viz_epoch_date": {
            "type": "splunk.singlevalue",
            "options": {
                "majorValue": "> primary | seriesByName('retarget') | lastPoint()",
                "sparklineDisplay": "off",
                "trendDisplay": "off",
                "majorColor": "#8a8fa8"
            },
            "title": "Est. retarget (UTC)",
            "dataSources": {
                "primary": "ds_epoch"
            }
        },
        "viz_halving_blocks": {
            "type": "splunk.singlevalue",
            "options": {
                "majorValue": "> primary | seriesByName('halving_blocks') | lastPoint()",
                "sparklineDisplay": "off",
                "trendDisplay": "off",
                "numberPrecision": 0,
                "majorColor": "#f7931a"
            },
            "title": "Blocks to halving",
            "dataSources": {
                "primary": "ds_epoch"
            }
        },
        "viz_halving_date": {
            "type": "splunk.singlevalue",
            "options": {
                "majorValue": "> primary | seriesByName('halving_date') | lastPoint()",
                "sparklineDisplay": "off",
                "trendDisplay": "off",
                "majorColor": "#f7931a"
            },
            "title": "Est. halving date",
            "dataSources": {
                "primary": "ds_epoch"
            }
        },
        "viz_hashrate": {
            "type": "splunk.line",
            "options": {
                "legendDisplay": "bottom",
                "xAxisTitleVisibility": "hide",
                "nullValueDisplay": "connect",
                "seriesColors": [
                    "#5b6aa8",
                    "#ffc107",
                    "#1bd8f4"
                ],
                "overlayFields": [
                    "Difficulty (T)"
                ],
                "showOverlayY2Axis": true,
                "yAxisTitleText": "EH/s",
                "y2AxisTitleText": "Difficulty (T)"
            },
            "title": "Hashrate & difficulty",
            "dataSources": {
                "primary": "ds_hashrate"
            },
            "description": "Hashrate estimated per day as sum(difficulty x 2^32) / sum(block intervals)"
        },
        "viz_pool_ranking": {
            "type": "splunk.table",
            "options": {
                "count": 15,
                "columnFormat": {
                    "Share %": {
                        "rowBackgroundColors": "> table | seriesByName(\"Share %\") | rangeValue(shareColors)"
                    }
                }
            },
            "title": "Pool ranking",
            "dataSources": {
                "primary": "ds_pool_ranking"
            },
            "context": {
                "shareColors": [
                    {
                        "to": 5,
                        "value": "#2b2d42"
                    },
                    {
                        "from": 5,
                        "to": 15,
                        "value": "#3a4a8a"
                    },
                    {
                        "from": 15,
                        "to": 30,
                        "value": "#653b9c"
                    },
                    {
                        "from": 30,
                        "value": "#9339f4"
                    }
                ]
            }
        },
        "viz_pool_pie": {
            "type": "splunk.pie",
            "options": {},
            "title": "Pool dominance",
            "dataSources": {
                "primary": "ds_pool_top"
            }
        },
        "viz_pool_time": {
            "type": "splunk.area",
            "options": {
                "legendDisplay": "bottom",
                "xAxisTitleVisibility": "hide",
                "nullValueDisplay": "connect",
                "stackMode": "stacked100",
                "areaOpacity": 0.85,
                "yAxisTitleText": "% of blocks"
            },
            "title": "Pool dominance over time",
            "dataSources": {
                "primary": "ds_pool_time"
            }
        },
        "viz_difficulty_epochs": {
            "type": "splunk.table",
            "options": {
                "count": 10,
                "columnFormat": {
                    "Change %": {
                        "rowColors": "> table | seriesByName(\"Change %\") | rangeValue(changeColors)"
                    }
                }
            },
            "title": "Difficulty adjustments",
            "dataSources": {
                "primary": "ds_difficulty_epochs"
            },
            "description": "First epoch in range has no previous value; partial epochs are averaged over the blocks seen",
            "context": {
                "changeColors": [
                    {
                        "to": 0,
                        "value": "#dc3545"
                    },
                    {
                        "from": 0,
                        "value": "#3bcc49"
                    }
                ]
            }
        },
        "viz_fees_subsidy": {
            "type": "splunk.column",
            "options": {
                "legendDisplay": "bottom",
                "xAxisTitleVisibility": "hide",
                "stackMode": "stacked",
                "seriesColors": [
                    "#4a68b9",
                    "#f7931a",
                    "#ffc107"
                ],
                "overlayFields": [
                    "Fee share %"
                ],
                "showOverlayY2Axis": true,
                "yAxisTitleText": "BTC",
                "y2AxisTitleText": "Fee share %"
            },
            "title": "Block rewards: subsidy vs fees",
            "dataSources": {
                "primary": "ds_fees_subsidy"
            }
        },
        "viz_fees_usd": {
            "type": "splunk.area",
            "options": {
                "legendDisplay": "bottom",
                "xAxisTitleVisibility": "hide",
                "nullValueDisplay": "connect",
                "seriesColors": [
                    "#4a68b9",
                    "#f7931a"
                ],
                "areaOpacity": 0.3,
                "yAxisTitleText": "USD"
            },
            "title": "Block rewards in USD",
            "dataSources": {
                "primary": "ds_fees_usd"
            },
            "description": "BTC amounts per bucket x average btc:prices USD in the same bucket"
        },
        "viz_avg_fee": {
            "type": "splunk.column",
            "options": {
                "legendDisplay": "off",
                "xAxisTitleVisibility": "hide",
                "seriesColors": [
                    "#f7931a"
                ],
                "yAxisTitleText": "sats"
            },
            "title": "Average fee per transaction",
            "dataSources": {
                "primary": "ds_avg_fee"
            }
        },
        "viz_fee_percentiles": {
            "type": "splunk.line",
            "options": {
                "legendDisplay": "bottom",
                "xAxisTitleVisibility": "hide",
                "nullValueDisplay": "connect",
                "yAxisScale": "log",
                "yAxisTitleText": "sat/vB",
                "seriesColors": [
                    "#557d00",
                    "#757d05",
                    "#957d0b",
                    "#ffc107",
                    "#bd5c28",
                    "#b30e55"
                ]
            },
            "title": "Block fee rates (percentiles)",
            "dataSources": {
                "primary": "ds_fee_percentiles"
            },
            "description": "Per-transaction fee rates of confirmed transactions (zero-fee package parents excluded), log scale"
        },
        "viz_fee_bands_time": {
            "type": "splunk.area",
            "options": {
                "legendDisplay": "right",
                "xAxisTitleVisibility": "hide",
                "nullValueDisplay": "connect",
                "stackMode": "stacked",
                "areaOpacity": 1,
                "seriesColorsByField": {
                    "<1": "#557d00",
                    "1-2": "#5d7d01",
                    "2-3": "#637d02",
                    "3-4": "#6d7d04",
                    "4-6": "#757d05",
                    "6-8": "#867d08",
                    "8-10": "#8c7d09",
                    "10-15": "#957d0b",
                    "15-20": "#a67d0e",
                    "20-30": "#b27d10",
                    "30-50": "#bf7815",
                    "50-100": "#bd5c28",
                    "100-200": "#bb3d3c",
                    "200+": "#b30e55"
                },
                "yAxisTitleText": "vMB"
            },
            "title": "Confirmed vMB by fee rate",
            "dataSources": {
                "primary": "ds_fee_bands_time"
            },
            "description": "The mempool.space 'Memory usage by fee rate' chart, but for vbytes confirmed per bucket"
        },
        "viz_fee_bands_total": {
            "type": "splunk.bar",
            "options": {
                "stackMode": "stacked100",
                "seriesColorsByField": {
                    "<1": "#557d00",
                    "1-2": "#5d7d01",
                    "2-3": "#637d02",
                    "3-4": "#6d7d04",
                    "4-6": "#757d05",
                    "6-8": "#867d08",
                    "8-10": "#8c7d09",
                    "10-15": "#957d0b",
                    "15-20": "#a67d0e",
                    "20-30": "#b27d10",
                    "30-50": "#bf7815",
                    "50-100": "#bd5c28",
                    "100-200": "#bb3d3c",
                    "200+": "#b30e55"
                },
                "legendDisplay": "bottom",
                "xAxisTitleVisibility": "hide",
                "yAxisTitleVisibility": "hide"
            },
            "title": "Block space by fee rate (range total)",
            "dataSources": {
                "primary": "ds_fee_bands_total"
            }
        },
        "viz_size_weight": {
            "type": "splunk.line",
            "options": {
                "legendDisplay": "bottom",
                "xAxisTitleVisibility": "hide",
                "nullValueDisplay": "connect",
                "seriesColors": [
                    "#f7931a",
                    "#4a68b9",
                    "#8a8fa8"
                ],
                "overlayFields": [
                    "Full %"
                ],
                "showOverlayY2Axis": true,
                "yAxisTitleText": "MB / MWU",
                "y2AxisTitleText": "Full %"
            },
            "title": "Block sizes & weights",
            "dataSources": {
                "primary": "ds_size_weight"
            }
        },
        "viz_tx_count": {
            "type": "splunk.column",
            "options": {
                "legendDisplay": "bottom",
                "xAxisTitleVisibility": "hide",
                "seriesColors": [
                    "#1bd8f4",
                    "#4a68b9"
                ],
                "overlayFields": [
                    "Avg TXs per block"
                ],
                "showOverlayY2Axis": true,
                "yAxisTitleText": "TXs confirmed",
                "y2AxisTitleText": "Avg per block"
            },
            "title": "Transactions",
            "dataSources": {
                "primary": "ds_tx_count"
            }
        },
        "viz_block_time": {
            "type": "splunk.line",
            "options": {
                "legendDisplay": "bottom",
                "xAxisTitleVisibility": "hide",
                "nullValueDisplay": "connect",
                "seriesColors": [
                    "#4a68b9",
                    "#8a8fa8",
                    "#f7931a"
                ],
                "overlayFields": [
                    "Blocks"
                ],
                "showOverlayY2Axis": true,
                "yAxisTitleText": "minutes",
                "y2AxisTitleText": "blocks"
            },
            "title": "Block interval",
            "dataSources": {
                "primary": "ds_block_time"
            }
        },
        "viz_interval_hist": {
            "type": "splunk.column",
            "options": {
                "seriesColors": [
                    "#9339f4"
                ],
                "legendDisplay": "off"
            },
            "title": "Block interval distribution",
            "dataSources": {
                "primary": "ds_interval_hist"
            },
            "description": "Should look exponential with a mean of ~10 min"
        },
        "viz_vsize": {
            "type": "splunk.line",
            "options": {
                "legendDisplay": "bottom",
                "xAxisTitleVisibility": "hide",
                "nullValueDisplay": "connect",
                "seriesColors": [
                    "#f7931a",
                    "#1bd8f4"
                ],
                "yAxisTitleText": "vB"
            },
            "title": "Transaction vsize",
            "dataSources": {
                "primary": "ds_vsize"
            }
        },
        "viz_long_gaps": {
            "type": "splunk.table",
            "options": {
                "count": 10
            },
            "title": "Block gaps >= 60 min",
            "dataSources": {
                "primary": "ds_long_gaps"
            }
        },
        "viz_adoption": {
            "type": "splunk.line",
            "options": {
                "legendDisplay": "bottom",
                "xAxisTitleVisibility": "hide",
                "nullValueDisplay": "connect",
                "seriesColors": [
                    "#3bcc49",
                    "#9339f4",
                    "#1bd8f4",
                    "#f7931a"
                ],
                "yAxisTitleText": "% of transactions"
            },
            "title": "SegWit / Taproot / RBF adoption",
            "dataSources": {
                "primary": "ds_adoption"
            },
            "description": "Share of non-coinbase transactions per bucket"
        },
        "viz_out_types": {
            "type": "splunk.area",
            "options": {
                "legendDisplay": "bottom",
                "xAxisTitleVisibility": "hide",
                "nullValueDisplay": "connect",
                "stackMode": "stacked100",
                "areaOpacity": 0.9,
                "seriesColorsByField": {
